mapper.select:
SELECT message_id AS messageId, COUNT(*) AS receiverCount, SUM(CASE WHEN read_flag = 1 THEN 1 ELSE 0 END) AS readCount, SUM(CASE WHEN read_flag = 0 THEN 1 ELSE 0 END) AS unreadCount FROM sys_message_receiver WHERE message_id IN
#{messageId}
GROUP BY message_id

SELECT m.id, m.title, m.content, m.type, m.send_channel, r.read_flag, r.read_time, m.create_time, m.biz_type, m.biz_key
FROM sys_message_receiver r
INNER JOIN sys_message m ON r.message_id = m.id
WHERE r.user_id = #{userId}
AND m.send_channel = 'WEB'
 AND r.read_flag = #{readFlag} 
 AND m.type = #{type} 
 AND (m.title LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%')) 
 AND m.create_time >= #{startTime} 
 AND m.create_time <= #{endTime} 
ORDER BY r.create_time DESC

