UPDATE sys_message_receiver
SET read_flag = 1,
    read_time = #{readTime}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND read_flag = 0

UPDATE sys_message_receiver
SET delivery_status = #{deliveryStatus},
    delivery_attempts = IFNULL(delivery_attempts, 0) + 1,
    external_id = #{externalId},
    last_error_code = #{lastErrorCode},
    last_attempt_time = #{lastAttemptTime},
    next_retry_time = #{nextRetryTime}
WHERE message_id = #{messageId}
  AND user_id = #{userId}

mapper.select:
SELECT r.*
FROM sys_message_receiver r
WHERE r.tenant_id = #{tenantId}
  AND r.delivery_status = 'FAILED'
  AND r.next_retry_time IS NOT NULL
  AND r.next_retry_time <= #{now}
ORDER BY r.next_retry_time ASC
LIMIT #{limitSize}
